package org.jlinalg.cli;

import java.io.IOException;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.jlinalg.assembly.HifiasmGfa;
import org.jlinalg.assembly.HifiasmReads;
import static org.jlinalg.cli.Monocle3WorkflowRequest.*;

/** Typed bounded source-profile request; no shell fragments or unvalidated option passthrough. */
final class HifiasmWorkflowRequest {
    private HifiasmWorkflowRequest(){ }
    record Input(String id,Path path,NextflowFiles.Pin pin,String kind){ }
    record Pair(String first,String second){ }
    record Analysis(String id,String mode,List<String> reads,List<String> ultralong,List<Pair> hic,String paternal,String maternal,int threads,int bloomBits,Integer purgeLevel,boolean disablePostJoin){
        Analysis{reads=List.copyOf(reads);ultralong=List.copyOf(ultralong);hic=List.copyOf(hic);}
    }
    record Limits(HifiasmReads.Limits reads,HifiasmGfa.Limits graph,int parentEntriesPerBucket,RsemProcess.Limits process){ }
    record Request(Path source,Path out,Path runtime,String edition,List<Input> inputs,List<Analysis> analyses,Limits limits){Request{inputs=List.copyOf(inputs);analyses=List.copyOf(analyses);}}
    private static long number(Map<String,Object> map,String name,long fallback,long maximum)throws IOException{return map.containsKey(name)?integer(map.get(name),1,maximum):fallback;}
    private static String id(Object raw)throws IOException{String value=text(raw);require(value.matches("[A-Za-z][A-Za-z0-9_.-]{0,63}"),"Use literal ASCII identifiers beginning with a letter, at most64 characters");return value;}
    private static List<String> names(Object raw,boolean optional)throws IOException{if(raw==null&&optional)return List.of();var result=new ArrayList<String>();for(Object value:list(raw))result.add(id(value));require(result.size()<129&&(optional||!result.isEmpty())&&new HashSet<>(result).size()==result.size(),"Declare1..128 distinct main files, or0..128 distinct auxiliary files");return result;}
    static Request read(Path source)throws IOException{
        source=HifiasmRuntime.regular(source,16777216);var root=GseapyExecutionRuntime.read(source,16777216);GseapyWorkflowRequest.allowed(root,"schema_version","out","runtime","edition","inputs","analyses","limits_profile","limits");integer(root.get("schema_version"),1,1);require(text(root.get("limits_profile")).equals("bounded-v1"),"Declare limits_profile bounded-v1 and inspect its effective capacities before large assemblies");String edition=text(root.get("edition"));require(object(HifiasmRuntime.profile().get("editions")).containsKey(edition),"Declare one exact packaged original edition");Path out=Path.of(text(root.get("out"))).toAbsolutePath().normalize(),runtime=Path.of(text(root.get("runtime"))).toAbsolutePath().normalize();require(out.getParent()!=null&&out.getParent().equals(out.getParent().toRealPath())&&!java.nio.file.Files.exists(out,java.nio.file.LinkOption.NOFOLLOW_LINKS),"Require NEW output under an existing canonical parent");
        var cap=root.containsKey("limits")?object(root.get("limits")):Map.<String,Object>of();GseapyWorkflowRequest.allowed(cap,"input_bytes","decoded_bytes","read_line_bytes","read_bases","read_records","total_bases","header_bytes","graph_bytes","graph_line_bytes","graph_records","graph_segments","graph_links","graph_placements","graph_bases","graph_coordinate","parent_entries_per_bucket","wall_seconds","address_space_bytes","cpu_seconds","file_bytes","open_files","workspace_bytes","maximum_files","maximum_processes","maximum_threads","sampled_rss_bytes");
        var reads=new HifiasmReads.Limits(number(cap,"input_bytes",268435456,1000000000000L),number(cap,"decoded_bytes",536870912,1000000000000L),(int)number(cap,"read_line_bytes",8000000,100000000),(int)number(cap,"read_bases",8000000,100000000),(int)number(cap,"read_records",1000000,25000000),number(cap,"total_bases",200000000,1000000000000L),number(cap,"header_bytes",33554432,1073741824));
        var graph=new HifiasmGfa.Limits(number(cap,"graph_bytes",67108864,1000000000000L),(int)number(cap,"graph_line_bytes",16000000,1000000000),(int)number(cap,"graph_records",1000000,100000000),(int)number(cap,"graph_segments",1000000,25000000),(int)number(cap,"graph_links",1000000,100000000),(int)number(cap,"graph_placements",1000000,100000000),number(cap,"graph_bases",200000000,1000000000000L),number(cap,"graph_coordinate",1000000000000L,Long.MAX_VALUE));
        var process=new RsemProcess.Limits(Math.multiplyExact(number(cap,"wall_seconds",600,604800),1000),number(cap,"address_space_bytes",8589934592L,1099511627776L),number(cap,"cpu_seconds",600,604800),number(cap,"file_bytes",1073741824,1000000000000L),(int)number(cap,"open_files",1024,1048576),number(cap,"workspace_bytes",2147483648L,1000000000000L),(int)number(cap,"maximum_files",4096,1000000),(int)number(cap,"maximum_processes",32,4096),(int)number(cap,"maximum_threads",256,1048576),number(cap,"sampled_rss_bytes",6442450944L,1099511627776L),100);var limits=new Limits(reads,graph,(int)number(cap,"parent_entries_per_bucket",4000000,25000000),process);
        var inputs=new ArrayList<Input>();var kinds=new java.util.LinkedHashMap<String,String>();for(var entry:object(root.get("inputs")).entrySet()){String key=id(entry.getKey());var spec=object(entry.getValue());GseapyWorkflowRequest.allowed(spec,"path","bytes","sha256","kind");String kind=text(spec.get("kind"));require(Set.of("reads","yak").contains(kind),"Input kind must be reads or yak");Path file=Path.of(text(spec.get("path"))).toAbsolutePath().normalize();require(!file.startsWith(out),"Input cannot be under this NEW output");inputs.add(new Input(key,file,NextflowFiles.fingerprint(spec,reads.encodedBytes()),kind));kinds.put(key,kind);}require(!inputs.isEmpty()&&inputs.size()<=256,"Declare1..256 original inputs");
        var analyses=new ArrayList<Analysis>();var ids=new HashSet<String>();var used=new HashSet<String>();for(Object value:list(root.get("analyses"))){var spec=object(value);GseapyWorkflowRequest.allowed(spec,"id","mode","reads","ultralong","hic_pairs","paternal","maternal","threads","bloom_bits","purge_level","disable_post_join");String key=id(spec.get("id")),mode=text(spec.get("mode"));require(ids.add(key)&&Set.of("hifi","trio","hic","hifi-ul","trio-ul","hic-ul","ont").contains(mode),"Duplicate analysis identity or unknown assembly mode");var main=names(spec.get("reads"),false);var ul=names(spec.get("ultralong"),true);var pairs=new ArrayList<Pair>();if(spec.containsKey("hic_pairs"))for(Object pair:list(spec.get("hic_pairs"))){var p=object(pair);GseapyWorkflowRequest.allowed(p,"first","second");pairs.add(new Pair(id(p.get("first")),id(p.get("second"))));}require(pairs.size()<=128,"Hi-C file-pair capacity exceeded");String paternal=spec.containsKey("paternal")?id(spec.get("paternal")):null,maternal=spec.containsKey("maternal")?id(spec.get("maternal")):null;require(mode.endsWith("-ul")==!ul.isEmpty()&&mode.startsWith("hic")==!pairs.isEmpty()&&mode.startsWith("trio")== (paternal!=null&&maternal!=null)&&((paternal==null)==(maternal==null)),"Mode and complete declared UL/Hi-C/trio inputs disagree");require(ul.size()<=1,"This source profile accepts one explicit UL file; combine files separately with preserved provenance");
            var readKeys=new ArrayList<String>(main);readKeys.addAll(ul);for(Pair pair:pairs){require(!pair.first().equals(pair.second()),"Hi-C mates must be distinct declared files");readKeys.add(pair.first());readKeys.add(pair.second());}for(String name:readKeys){require("reads".equals(kinds.get(name)),"Unknown or non-read input: "+name);used.add(name);}if(paternal!=null){require(!paternal.equals(maternal)&&"yak".equals(kinds.get(paternal))&&"yak".equals(kinds.get(maternal)),"Trio requires two distinct original YAK inputs");used.add(paternal);used.add(maternal);}
            int threads=Math.toIntExact(integer(spec.get("threads"),1,256)),bloom=Math.toIntExact(integer(spec.get("bloom_bits"),0,40));require(bloom==0||bloom>=20,"Bloom bits must be0 (explicitly disabled) or20..40");if(bloom>0)require((1L<<(bloom-3))<process.addressSpaceBytes(),"Declared Bloom allocation alone reaches/exceeds the original process address-space limit");Integer purge=spec.containsKey("purge_level")?Math.toIntExact(integer(spec.get("purge_level"),0,3)):null;boolean disable=spec.containsKey("disable_post_join")&&bool(spec.get("disable_post_join"));analyses.add(new Analysis(key,mode,main,ul,pairs,paternal,maternal,threads,bloom,purge,disable));
        }
        require(!analyses.isEmpty()&&analyses.size()<=32&&used.equals(kinds.keySet()),"Declare1..32 analyses and use every declared input");if(analyses.stream().anyMatch(a->!a.hic().isEmpty()))require(!out.toString().contains(","),"A Hi-C output path cannot contain a comma: the original --h1/--h2 parameters use comma-separated file lists");return new Request(source,out,runtime,edition,inputs,analyses,limits);
    }
    static void available(Request request)throws IOException{
        for(Analysis analysis:request.analyses()){
            if(analysis.mode().startsWith("hic")&&Set.of("0.14.2-r315","0.15.1-r328").contains(request.edition()))throw new RsemProcess.UnavailableDependency("Hi-C in exact editions0.14.2/0.15.1 is excluded after retained original crashes; supply a compatible separately validated newer edition, or keep the requested old-edition analysis skipped");
            if(analysis.mode().endsWith("-ul")&&!Set.of("0.19.5-r587","0.19.5-r592","0.22.0-r689").contains(request.edition()))throw new RsemProcess.UnavailableDependency("UL assembly is not admitted for this exact older source edition");
            if(analysis.mode().equals("ont")&&!request.edition().equals("0.22.0-r689"))throw new RsemProcess.UnavailableDependency("ONT-only assembly requires the admitted0.22.0-r689 source profile and FASTQ qualities");
        }
    }
}
